def get_input():
    """Get user input and prompt for data type conversion."""
    while True:
        try:
            user_input = float(input("Enter a value: "))
            break
        except ValueError:
            print("Invalid input. Please enter a number.")

    while True:
        data_type = input("Choose a data type (int, float, str): ").lower()
        if data_type in ['int', 'float', 'str']:
            break
        else:
            print("Invalid data type. Please choose either 'int', 'float', or 'str'.")

    return user_input, data_type

def convert_data_type(value, data_type):
    """Convert a value to a specific data type."""
    if data_type == 'int':
        return int(value)
    elif data_type == 'float':
        return float(value)
    elif data_type == 'str':
        return str(value)

def main():
    user_input, data_type = get_input()
    converted_value = convert_data_type(user_input, data_type)
    print(f"{user_input} converted to {data_type}: {converted_value}")

if __name__ == "__main__":
    main()
```

This program defines three functions: `get_input()`, `convert_data_type()`, and `main()`. The `get_input()` function gets user input and prompts for a data type conversion. The `convert_data_type()` function converts a value to a specific data type based on the user's choice. Finally, the `main()` function calls the other two functions and prints out the converted value.
